from pathlib import Path
import importlib,os,subprocess,sys

ROOT=Path.cwd().resolve()
PKG=ROOT/"qseries_v2"/"oracle_production_learning"

MOD=PKG/"opl_007_evidence_first_outcome_resolver.py"
TEST=ROOT/"test_opl_007_evidence_first_outcome_resolver.py"
INIT=PKG/"__init__.py"
OPL004=PKG/"opl_004_24x7_production_learning_runtime.py"

MODULE_SOURCE='from __future__ import annotations\nfrom dataclasses import dataclass,asdict\nfrom pathlib import Path\nfrom hashlib import sha256\nimport json\n\nfrom .opl_001_production_learning_foundation import (\n    connect,STATE_TABLE,LEDGER_TABLE,ensure_production_learning_schema\n)\nfrom .opl_002_canonical_evidence_index import (\n    INDEX_TABLE,\n    sync_evidence_index,\n)\n\nOPL_007_BUILD_ID="OPL-007"\nOPL_007_REVISION="OPL_007_EVIDENCE_FIRST_OUTCOME_RESOLVER_V1"\n\n@dataclass(frozen=True)\nclass EvidenceCandidate:\n    ticker:str\n    observation_id:str\n    evidence_hash:str\n    sequence_number:int\n    observed_at:str\n    observation_type:str\n\n@dataclass(frozen=True)\nclass SettledOutcome:\n    ticker:str\n    result:str\n    settlement_ts:str\n    source_hash:str\n    raw:dict\n\n@dataclass(frozen=True)\nclass EvidenceFirstLearningSummary:\n    evidence_candidates:int\n    settlement_checked:int\n    settled:int\n    already_learned:int\n    evidence_matched:int\n    admitted:int\n    applied:int\n    production_learned_total:int\n    learning_yield:float\n    state_hash:str\n\ndef _h(v):\n    return sha256(\n        json.dumps(v,sort_keys=True,separators=(",",":"),default=str).encode()\n    ).hexdigest()\n\ndef _credentials(root):\n    from qseries_v2.oracle_adapters.kalshi.oad_021_credentials import load_kalshi_credentials\n    return load_kalshi_credentials(root=root)\n\ndef _get(credentials,path,params=None,timeout=15):\n    from qseries_v2.oracle_adapters.kalshi.oad_022_rest_transport import kalshi_rest_get\n    return kalshi_rest_get(credentials,path,params or {},timeout)\n\ndef _normalize_market(raw):\n    raw=dict(raw)\n    ticker=str(raw.get("ticker") or "").strip().upper()\n    result=str(raw.get("result") or "").strip().lower()\n    settlement_ts=str(\n        raw.get("settlement_ts")\n        or raw.get("settled_ts")\n        or raw.get("settled_time")\n        or ""\n    ).strip()\n    status=str(raw.get("status") or "").strip().lower()\n\n    if not ticker:\n        return None\n    if status!="settled":\n        return None\n    if result not in ("yes","no","scalar"):\n        return None\n    if not settlement_ts:\n        return None\n\n    return SettledOutcome(\n        ticker=ticker,\n        result=result,\n        settlement_ts=settlement_ts,\n        source_hash=_h(raw),\n        raw=raw,\n    )\n\ndef _load_ocl_state(raw):\n    from qseries_v2.oracle_continuous_learner.ocl_027_incremental_state_runtime import (\n        IncrementalLearnerState,\n        genesis_incremental_state,\n    )\n    if not raw:\n        return genesis_incremental_state()\n    return IncrementalLearnerState(**dict(raw))\n\ndef _build_runtime_input(sequence,outcome,evidence):\n    from qseries_v2.oracle_continuous_learner.ocl_003_outcome_observation import (\n        build_outcome_observation,\n    )\n    from qseries_v2.oracle_continuous_learner.ocl_004_learning_event import (\n        assemble_learning_event,\n    )\n    from qseries_v2.oracle_continuous_learner.ocl_026_continuous_intake_runtime import (\n        build_runtime_input,\n    )\n\n    value=(\n        True if outcome.result=="yes"\n        else False if outcome.result=="no"\n        else outcome.raw.get("settlement_value")\n    )\n\n    oo=build_outcome_observation(\n        outcome.ticker,\n        "settlement",\n        value,\n        outcome.settlement_ts,\n        "kalshi:"+outcome.ticker,\n        outcome.source_hash,\n    )\n\n    lineage=sha256(\n        (evidence.evidence_hash+outcome.source_hash).encode()\n    ).hexdigest()\n\n    event=assemble_learning_event(\n        outcome.ticker,\n        evidence.evidence_hash,\n        lineage,\n        oo,\n    )\n\n    ri=build_runtime_input(\n        int(sequence),\n        "learning_event",\n        event.event_id,\n        event.event_hash,\n        {\n            "subject_id":event.subject_id,\n            "evidence_hash":event.evidence_hash,\n            "outcome_hash":event.outcome_hash,\n            "lineage_hash":event.lineage_hash,\n            "outcome_type":event.outcome_type,\n        },\n    )\n    return ri,event.event_hash\n\ndef collect_evidence_candidates(root=None,limit=5000):\n    root=Path(root or Path.cwd()).resolve()\n    with connect(root) as conn:\n        with conn.cursor() as cur:\n            cur.execute(\n                f"""\n                WITH ranked AS (\n                    SELECT\n                        ticker,\n                        observation_id,\n                        evidence_hash,\n                        sequence_number,\n                        observed_at,\n                        observation_type,\n                        ROW_NUMBER() OVER (\n                            PARTITION BY ticker\n                            ORDER BY sequence_number DESC\n                        ) AS rn\n                    FROM public.{INDEX_TABLE}\n                )\n                SELECT\n                    r.ticker,\n                    r.observation_id,\n                    r.evidence_hash,\n                    r.sequence_number,\n                    r.observed_at,\n                    r.observation_type\n                FROM ranked r\n                LEFT JOIN public.{LEDGER_TABLE} l\n                    ON l.ticker=r.ticker\n                   AND l.status=\'LEARNED\'\n                WHERE r.rn=1\n                  AND l.ticker IS NULL\n                ORDER BY r.sequence_number DESC\n                LIMIT %s\n                """,\n                (int(limit),),\n            )\n            rows=cur.fetchall()\n\n    return tuple(\n        EvidenceCandidate(\n            str(r[0]).upper(),\n            str(r[1]),\n            str(r[2]),\n            int(r[3]),\n            str(r[4]),\n            str(r[5]),\n        )\n        for r in rows\n    )\n\ndef resolve_settlement(credentials,ticker):\n    ticker=str(ticker).strip().upper()\n    if not ticker:\n        return None\n\n    r=_get(credentials,f"/markets/{ticker}",{},15)\n    body=dict(r.body or {})\n    raw=body.get("market") if isinstance(body.get("market"),dict) else body\n    if not isinstance(raw,dict):\n        return None\n\n    return _normalize_market(raw)\n\ndef collect_evidence_supported_settlements(\n    root=None,\n    candidate_limit=5000,\n    target_settled=250,\n    progress=print,\n):\n    root=Path(root or Path.cwd()).resolve()\n    credentials=_credentials(root)\n    candidates=collect_evidence_candidates(root,candidate_limit)\n\n    checked=0\n    settled=[]\n    missing=0\n\n    for i,e in enumerate(candidates,1):\n        checked+=1\n        try:\n            outcome=resolve_settlement(credentials,e.ticker)\n        except Exception as exc:\n            progress(\n                f"[OPL EVIDENCE-FIRST] settlement_lookup_error "\n                f"ticker={e.ticker} type={type(exc).__name__}"\n            )\n            continue\n\n        if outcome is None:\n            missing+=1\n        else:\n            # Enforce strict pre-settlement evidence.\n            if str(e.observed_at) < str(outcome.settlement_ts):\n                settled.append((e,outcome))\n\n        if i==1 or i%100==0 or settled:\n            progress(\n                f"[OPL EVIDENCE-FIRST] checked={checked} "\n                f"settled={len(settled)} unresolved={missing}"\n            )\n\n        if len(settled)>=int(target_settled):\n            break\n\n    return tuple(settled),len(candidates),checked,missing\n\ndef run_evidence_first_learning_cycle(\n    root=None,\n    candidate_limit=5000,\n    target_settled=250,\n    progress=print,\n):\n    from qseries_v2.oracle_continuous_learner.ocl_026_continuous_intake_runtime import (\n        assemble_runtime_batch,\n    )\n    from qseries_v2.oracle_continuous_learner.ocl_028_learning_cycle_orchestrator import (\n        run_learning_cycle,\n    )\n\n    root=Path(root or Path.cwd()).resolve()\n    ensure_production_learning_schema(root)\n\n    sync=sync_evidence_index(\n        root,\n        batch_size=5000,\n        max_batches=10,\n        backfill_if_empty=100000,\n    )\n\n    supported,candidate_count,checked,unresolved=collect_evidence_supported_settlements(\n        root=root,\n        candidate_limit=candidate_limit,\n        target_settled=target_settled,\n        progress=progress,\n    )\n\n    with connect(root) as conn:\n        with conn.cursor() as cur:\n            cur.execute(\n                f"""\n                SELECT\n                    production_outcomes_learned,\n                    cycles,\n                    applied_through_sequence,\n                    ocl_state_json,\n                    state_hash\n                FROM public.{STATE_TABLE}\n                WHERE state_id=1\n                FOR UPDATE\n                """\n            )\n            prod,cycles,through,raw_state,state_hash=cur.fetchone()\n            ocl=_load_ocl_state(raw_state)\n\n            inputs=[]\n            pending=[]\n            seq=int(through)\n            already_learned=0\n\n            for evidence,outcome in supported:\n                cur.execute(\n                    f"""\n                    SELECT status\n                    FROM public.{LEDGER_TABLE}\n                    WHERE settlement_hash=%s\n                    """,\n                    (outcome.source_hash,),\n                )\n                old=cur.fetchone()\n                if old and str(old[0])=="LEARNED":\n                    already_learned+=1\n                    continue\n\n                seq+=1\n                ri,event_hash=_build_runtime_input(seq,outcome,evidence)\n                inputs.append(ri)\n                pending.append((evidence,outcome,event_hash))\n\n                cur.execute(\n                    f"""\n                    INSERT INTO public.{LEDGER_TABLE}\n                    (\n                        settlement_hash,ticker,result,settlement_ts,\n                        evidence_observation_id,evidence_hash,\n                        evidence_sequence_number,learning_event_hash,status\n                    )\n                    VALUES(%s,%s,%s,%s,%s,%s,%s,%s,\'ELIGIBLE\')\n                    ON CONFLICT(settlement_hash) DO UPDATE SET\n                        evidence_observation_id=EXCLUDED.evidence_observation_id,\n                        evidence_hash=EXCLUDED.evidence_hash,\n                        evidence_sequence_number=EXCLUDED.evidence_sequence_number,\n                        learning_event_hash=EXCLUDED.learning_event_hash,\n                        status=\'ELIGIBLE\',\n                        updated_at=clock_timestamp()\n                    """,\n                    (\n                        outcome.source_hash,\n                        outcome.ticker,\n                        outcome.result,\n                        outcome.settlement_ts,\n                        evidence.observation_id,\n                        evidence.evidence_hash,\n                        evidence.sequence_number,\n                        event_hash,\n                    ),\n                )\n\n            applied=0\n\n            if inputs:\n                batch=assemble_runtime_batch(tuple(inputs))\n                result,new_ocl=run_learning_cycle(\n                    int(cycles)+1,\n                    ocl,\n                    batch,\n                )\n\n                applied=len(inputs)\n                prod=int(prod)+applied\n                cycles=int(cycles)+1\n\n                last=max(\n                    pending,\n                    key=lambda x:(x[1].settlement_ts,x[1].ticker),\n                )[1]\n\n                for evidence,outcome,event_hash in pending:\n                    cur.execute(\n                        f"""\n                        UPDATE public.{LEDGER_TABLE}\n                        SET\n                            status=\'LEARNED\',\n                            learned_at=clock_timestamp(),\n                            updated_at=clock_timestamp()\n                        WHERE settlement_hash=%s\n                        """,\n                        (outcome.source_hash,),\n                    )\n\n                cur.execute(\n                    f"""\n                    UPDATE public.{STATE_TABLE}\n                    SET\n                        production_outcomes_learned=%s,\n                        cycles=%s,\n                        applied_through_sequence=%s,\n                        ocl_state_json=%s::jsonb,\n                        last_settlement_ts=%s,\n                        last_ticker=%s,\n                        state_hash=%s,\n                        updated_at=clock_timestamp()\n                    WHERE state_id=1\n                    """,\n                    (\n                        prod,\n                        cycles,\n                        int(new_ocl.applied_through_sequence),\n                        json.dumps(asdict(new_ocl),sort_keys=True),\n                        last.settlement_ts,\n                        last.ticker,\n                        new_ocl.state_hash,\n                    ),\n                )\n\n                state_hash=new_ocl.state_hash\n\n                progress(\n                    f"[OPL LEARN] applied={applied} "\n                    f"production_total={prod} cycle={cycles} "\n                    f"through_sequence={new_ocl.applied_through_sequence}"\n                )\n                progress(\n                    f"[OPL LEARN] state_hash={new_ocl.state_hash} "\n                    f"cycle_hash={result.cycle_hash}"\n                )\n\n        conn.commit()\n\n    settled_count=len(supported)\n    yield_=(applied/settled_count) if settled_count else 0.0\n\n    progress(\n        f"[OPL METRICS] evidence_candidates={candidate_count} "\n        f"settlement_checked={checked} settled={settled_count} "\n        f"evidence_matched={settled_count} admitted={len(inputs)} "\n        f"applied={applied} learning_yield={yield_:.3f} "\n        f"indexed={sync[\'inserted\']}"\n    )\n\n    return EvidenceFirstLearningSummary(\n        candidate_count,\n        checked,\n        settled_count,\n        already_learned,\n        settled_count,\n        len(inputs),\n        applied,\n        int(prod),\n        yield_,\n        str(state_hash or ""),\n    )\n\ndef verify_opl_007_evidence_first_outcome_resolver(root=None):\n    return (\n        OPL_007_BUILD_ID=="OPL-007"\n        and callable(collect_evidence_candidates)\n        and callable(resolve_settlement)\n        and callable(run_evidence_first_learning_cycle)\n    )\n'
TEST_SOURCE='import unittest\nfrom qseries_v2.oracle_production_learning.opl_007_evidence_first_outcome_resolver import *\n\nclass T(unittest.TestCase):\n    def test_identity(self):\n        self.assertEqual(OPL_007_BUILD_ID,"OPL-007")\n\n    def test_callable_contracts(self):\n        self.assertTrue(callable(collect_evidence_candidates))\n        self.assertTrue(callable(resolve_settlement))\n        self.assertTrue(callable(run_evidence_first_learning_cycle))\n\nif __name__=="__main__":\n    print("="*88)\n    print(" OPL-007 CERTIFICATION TEST")\n    print(" EVIDENCE-FIRST OUTCOME RESOLVER")\n    print("="*88)\n    r=unittest.TextTestRunner(verbosity=2).run(\n        unittest.defaultTestLoader.loadTestsFromTestCase(T)\n    )\n    if not r.wasSuccessful():\n        raise SystemExit(1)\n    print("[PASS] Evidence-first learning contracts certified")\n    print("[PASS] Settlement-first intake removed from production path")\n    print("[PASS] execution_authority=FALSE")\n    print("[DONE] OPL-007 CERTIFIED")\n'
OPL004_SOURCE='from __future__ import annotations\nfrom pathlib import Path\nimport argparse,time\n\nfrom .opl_007_evidence_first_outcome_resolver import run_evidence_first_learning_cycle\n\nOPL_004_BUILD_ID="OPL-004"\nOPL_004_REVISION="OPL_004_24X7_PRODUCTION_LEARNING_RUNTIME_CORRECTED_BY_OPL_007_V1"\n\ndef main(argv=None):\n    p=argparse.ArgumentParser()\n    p.add_argument("--cadence-seconds",type=float,default=15.0)\n    p.add_argument("--candidate-limit",type=int,default=5000)\n    p.add_argument("--target-settled",type=int,default=250)\n    p.add_argument("--once",action="store_true")\n    p.add_argument("--check",action="store_true")\n    a=p.parse_args(argv)\n\n    if a.check:\n        print("[READY] OPL-004 production learning runtime verified")\n        print("[PASS] evidence_first_outcome_resolution=ENABLED")\n        print("[PASS] execution_authority=FALSE")\n        return 0\n\n    if a.cadence_seconds<=0 or a.candidate_limit<1 or a.target_settled<1:\n        raise SystemExit("invalid arguments")\n\n    root=Path.cwd()\n    cycle=0\n\n    print("="*88,flush=True)\n    print(" OPL-004 ORACLE PRODUCTION LEARNING RUNTIME",flush=True)\n    print("="*88,flush=True)\n    print("[OPL] authority=LEARNING_ONLY execution_authority=FALSE",flush=True)\n    print("[OPL] evidence_first_outcome_resolution=ENABLED",flush=True)\n\n    while True:\n        cycle+=1\n        try:\n            s=run_evidence_first_learning_cycle(\n                root,\n                candidate_limit=a.candidate_limit,\n                target_settled=a.target_settled,\n                progress=lambda x:print(x,flush=True),\n            )\n            print(\n                f"[OPL] runtime_cycle={cycle} applied={s.applied} "\n                f"production_learned_total={s.production_learned_total} "\n                f"learning_yield={s.learning_yield:.3f}",\n                flush=True,\n            )\n        except Exception as exc:\n            print(\n                f"[OPL ERROR] type={type(exc).__name__} message={exc}",\n                flush=True,\n            )\n            if a.once:\n                raise\n\n        if a.once:\n            return 0\n\n        time.sleep(a.cadence_seconds)\n\ndef verify_opl_004_24x7_production_learning_runtime(root=None):\n    return OPL_004_BUILD_ID=="OPL-004" and callable(main)\n'

def write_exact(path,text):
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_suffix(path.suffix+".tmp")
    tmp.write_text(text,encoding="utf-8",newline="\n")
    os.replace(tmp,path)

def restore(path,data):
    if data is None:
        if path.exists():path.unlink()
    else:
        path.write_bytes(data)

def update_init(path,export):
    current=path.read_text(encoding="utf-8") if path.exists() else ""
    if export not in current.splitlines():
        write_exact(path,current.rstrip()+"\n"+export+"\n")

def main():
    print("="*88)
    print(" OPL-007 INSTALLER")
    print(" EVIDENCE-FIRST OUTCOME RESOLVER")
    print("="*88)
    print("[ROOT]",ROOT)

    sys.path.insert(0,str(ROOT))

    opl2=importlib.import_module(
        "qseries_v2.oracle_production_learning.opl_002_canonical_evidence_index"
    )
    if not opl2.verify_opl_002_canonical_evidence_index(ROOT):
        raise RuntimeError("Current OPL-002 verification failed")

    old={p:(p.read_bytes() if p.exists() else None) for p in (MOD,TEST,INIT,OPL004)}

    try:
        write_exact(MOD,MODULE_SOURCE)
        write_exact(TEST,TEST_SOURCE)
        update_init(INIT,"from .opl_007_evidence_first_outcome_resolver import *")

        subprocess.run([sys.executable,str(TEST)],cwd=str(ROOT),check=True)

        compile(OPL004_SOURCE,str(OPL004),"exec")
        write_exact(OPL004,OPL004_SOURCE)

        importlib.invalidate_caches()

        m=importlib.import_module(
            "qseries_v2.oracle_production_learning.opl_007_evidence_first_outcome_resolver"
        )
        m=importlib.reload(m)

        if not m.verify_opl_007_evidence_first_outcome_resolver(ROOT):
            raise RuntimeError("OPL-007 verification failed")

        r=importlib.import_module(
            "qseries_v2.oracle_production_learning.opl_004_24x7_production_learning_runtime"
        )
        r=importlib.reload(r)

        if not r.verify_opl_004_24x7_production_learning_runtime(ROOT):
            raise RuntimeError("Corrected OPL-004 verification failed")

        subprocess.run(
            [sys.executable,str(ROOT/"run_opl_004_production_learning_runtime.py"),"--check"],
            cwd=str(ROOT),
            check=True,
        )

    except Exception:
        for p,b in old.items():
            restore(p,b)
        print("[ROLLBACK] OPL-007 failed; production learning files restored")
        raise

    print("[PASS] Evidence index preserved")
    print("[PASS] OCL learning engine preserved")
    print("[PASS] OPL-004 switched to evidence-first outcome resolution")
    print("[PASS] Oracle Live launcher unchanged")
    print("[PASS] OPH architecture untouched")
    print("[PASS] execution_authority=FALSE")
    print("[DONE] OPL-007 INSTALLATION COMPLETE")

if __name__=="__main__":
    main()
